define({"topics":[{"title":"Doing a Physiological Acquisition Controller (PAC) respiratory test","shortdesc":"<p class=\"shortdesc\">The Physiological Acquisition Controller (PAC) respiratory test causes the PAC module to test its respiratory gain and offset circuits.<\/p>","href":"c_PAC-Resp_14922440.html","attributes":{"data-id":"id_13106305"},"menu":{"hasChildren":false},"tocID":"id_13106305-d46e59137","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) IF loopback test","shortdesc":"<p class=\"shortdesc\">The Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) IF loopback test verifies that the PAC TX and RX port on the ICE board (J38, J39) is functioning correctly.<\/p>","href":"c_SPU-to-PAC-IF-Loopback_14945168.html","attributes":{"data-id":"id_13106308"},"menu":{"hasChildren":false},"tocID":"id_13106308-d46e59244","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) loopback diagnostic","shortdesc":"<p class=\"shortdesc\">The Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) loopback diagnostic verifies that the ICE board can send data to the PAC module over the PAC's fiber optic cables.<\/p>","href":"c_SPU-to-PAC-Loopback_14922552.html","attributes":{"data-id":"id_13106306"},"menu":{"hasChildren":false},"tocID":"id_13106306-d46e59456","topics":[]},{"title":"Doing the Signal Protection Unit (SPU) to Field Programmable Gate Array (FPGA) loopback test","shortdesc":"<p class=\"shortdesc\">The Signal Protection Unit (SPU) to Field Programmable Gate Array (FPGA) loopback test verifies the data path in the PAC I\/F in the PSC FPGA on the Integrated Control Engine (ICE) board.<\/p>","href":"c_SPU-to-FPGA-Loopback_14947538_4.html","attributes":{"data-id":"id_13106309"},"menu":{"hasChildren":false},"tocID":"id_13106309-d46e59880","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) respiratory diagnostic","shortdesc":"<p class=\"shortdesc\">This Signal Processing Unit (SPU) respiratory diagnostic verifies that the trigger signals (respiratory trigger), which are launched from the SPU in Integrated Control Engine (ICE), could be correctly captured by the sequencer module in ICE.<\/p>","href":"r_diag_SPU-Respiratory-Diagnostics_14947547.html","attributes":{"data-id":"id_13106311"},"menu":{"hasChildren":false},"tocID":"id_13106311-d46e59987","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) cardiac diagnostic","shortdesc":"<p class=\"shortdesc\">The Signal Processing Unit (SPU) cardiac diagnostic verifies that the trigger signals (cardiac trigger), which are launched from SPU in Integrated Control Engine (ICE), could be correctly captured by the sequencer module in ICE.<\/p>","href":"r_diag_SPU-Cardiac-Diagnostics_14947545.html","attributes":{"data-id":"id_13106310"},"menu":{"hasChildren":false},"tocID":"id_13106310-d46e60092","topics":[]}]});